from __future__ import annotations
import cmath, math
from typing import Callable

Field = Callable[[float], complex]

def winding_by_unwrap(phi: Field, n: int = 20000) -> float:
    total = 0.0
    prev = phi(0.0)
    for k in range(1, n + 1):
        cur = phi(2.0 * math.pi * k / n)
        total += cmath.phase(cur / prev)
        prev = cur
    return total / (2.0 * math.pi)

def winding_by_contour(phi: Field, dphi: Field, n: int = 20000) -> complex:
    acc = 0.0 + 0.0j
    h = 2.0 * math.pi / n
    for k in range(n):
        theta = h * k
        acc += dphi(theta) / phi(theta)
    return (acc * h) / (2.0 * math.pi * 1j)

def oam_phase(ell: int) -> Field:
    return lambda theta: cmath.exp(1j * ell * theta)

def oam_phase_deriv(ell: int) -> Field:
    return lambda theta: 1j * ell * cmath.exp(1j * ell * theta)

for ell in range(-4, 5):
    w1 = winding_by_unwrap(oam_phase(ell))
    w2 = winding_by_contour(oam_phase(ell), oam_phase_deriv(ell))
    print(f'l={ell:+d}: unwrap={w1:+.6f}, contour={w2.real:+.6f}')

from __future__ import annotations
import cmath, math

def winding_by_unwrap(phi, n: int = 40000) -> float:
    total = 0.0
    prev = phi(0.0)
    for k in range(1, n + 1):
        cur = phi(2.0 * math.pi * k / n)
        total += cmath.phase(cur / prev)
        prev = cur
    return total / (2.0 * math.pi)

def g(theta: float) -> complex:
    return (2.0 + math.sin(5.0 * theta)) * cmath.exp(3j * theta)

w = winding_by_unwrap(g)
print(f'w(g) = {w:+.6f}  ->  integer charge {round(w):+d}')

