function COMBINE_CHARGES(factors):
    # factors: list of (charge_l, inverted?) pairs
    total <- 0
    for (l, inverted) in factors:
        if inverted:
            total <- total - l
        else:
            total <- total + l
    return total                          # topological charge of the product

